32	    expect(config.capacity).toBeGreaterThan(0);
33	    expect(config.refillPerMinute).toBeGreaterThan(0);
34	  });
35	
36	  it("allows a first request and reports the remaining tokens", async () => {
37	    const verdict = await consumeRateLimit(ORG_A, "member:invite");
38	    expect(verdict.allowed).toBe(true);
39	    expect(verdict.remaining).toBe(19);
40	  });
41	
42	  it("exhausts the bucket and then refuses", async () => {
43	    const capacity = getBucketConfig("auth:password-reset").capacity;
44	    for (let i = 0; i < capacity; i += 1) {
45	      expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(true);
46	    }
47	
48	    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
49	    expect(denied.allowed).toBe(false);
50	    expect(denied.remaining).toBe(0);
51	  });
52	
53	  it("refills over time at the declared rate", async () => {
54	    const { capacity, refillPerMinute } = getBucketConfig("auth:password-reset");
55	    for (let i = 0; i < capacity; i += 1) {
56	      await consumeRateLimit(ORG_A, "auth:password-reset");
57	    }
58	    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
59	
60	    vi.advanceTimersByTime(2 * 60_000);
61	    const after = await consumeRateLimit(ORG_A, "auth:password-reset");
62	    expect(after.allowed).toBe(true);
63	    expect(after.remaining).toBe(2 * refillPerMinute - 1);
64	  });
65	
66	  it("never refills past capacity", async () => {
67	    await consumeRateLimit(ORG_A, "member:invite");
68	    vi.advanceTimersByTime(24 * 60 * 60_000);
69	
70	    const verdict = await consumeRateLimit(ORG_A, "member:invite");
71	    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
72	  });
73	
74	  it("charges the supplied cost", async () => {
75	    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
76	    expect(verdict.allowed).toBe(true);
77	    expect(verdict.remaining).toBe(15);
