/**
 * Thread assembly and soft-deleted rows.
 *
 * Owner C implements `@/server/repositories/comment-repository`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let northIssue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind-comments");
  acme = await createTenant("acme-comments");

  const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
  northIssue = await issueRepo.insertIssue(
    issueInput(north.org.id, north.project.id, { title: "Thread carrier" }),
    north.userIds.owner,
    number,
  );
});

afterAll(() => {
  cleanup();
});

describe("repositories/comment-repository", () => {
  it("assembles top-level comments with their replies", async () => {
    const top = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "Top-level comment",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    const reply = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "A reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );

    const thread = await commentRepo.listThread(north.org.id, northIssue.id);
    const node = thread.find((n) => n.comment.id === top.id);

    expect(node).toBeDefined();
    expect(node?.replies.map((r) => r.id)).toEqual([reply.id]);
  });

  it("orders replies oldest first inside a thread", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Ordering thread" }),
      north.userIds.owner,
      number,
    );

    const top = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Parent",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    const first = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "First reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );
    const second = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Second reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );

    const thread = await commentRepo.listThread(north.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);

    expect(node?.replies.map((r) => r.id)).toEqual([first.id, second.id]);
  });

  it("hides soft-deleted comments from the default listing", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Soft delete listing" }),
      north.userIds.owner,
      number,
    );
    const comment = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Will be deleted",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    await commentRepo.archiveComment(north.org.id, comment.id);

    const page = await commentRepo.listComments({
      orgId: north.org.id,
      issueId: issue.id,
      limit: 25,
      cursor: null,
      includeArchived: false,
    });

    expect(page.items.map((row) => row.id)).not.toContain(comment.id);
  });

  it("scopes the thread to the organization, not just the issue", async () => {
    await expect(
      commentRepo.listThread(acme.org.id, northIssue.id),
    ).resolves.toEqual([]);
  });

  it("joins the author user record onto each comment", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Author join" }),
      north.userIds.owner,
      number,
    );
    await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Authored",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );

    const page = await commentRepo.listComments({
      orgId: north.org.id,
      issueId: issue.id,
      limit: 25,
      cursor: null,
      includeArchived: false,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.author.id).toBe(north.userIds.member);
    expect(page.items[0]?.author.email).toBe(`member@northwind-comments.test`);
  });
});

/**
 * Denormalised search index kept in step by `SearchService`.
 */
import { and, count, desc, eq, inArray, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { OrgId, Page, ProjectId } from "@/types/common";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';

