function isPastEditWindow(comment: Comment): boolean {
  // The window is fixed to the original post: an edit must never restart it,
  // or an author who edits once early stays editable indefinitely.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side, minus the comment's own author — a
 * self-mention is never recorded. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  authorId: UserId,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await listActiveMembers(orgId);

  const resolved = resolveMentions(body, members);
  const known = new Set(members.map((member) => member.userId));

  const merged = new Set([
    ...resolved,
    ...clientProvided.filter((id) => known.has(id)),
  ]);
  merged.delete(authorId);

  return [...merged];
}

/**
 * Every active member of the org, paged through in full — a workspace with
 * more members than fit on one page must still resolve mentions of its
 * longest-standing members, not just the most recently paged-in ones.
 */
async function listActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }

  return members;
}

