 * more members than fit on one page must still resolve mentions of its
 * longest-standing members, not just the most recently paged-in ones.
 */
async function listActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }

  return members;
}

