input.new_string:
/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply descending from it — directly or
 * through other replies — in posting order. A deleted comment keeps its row
 * as a textless placeholder so replies anchored underneath it, at any depth,
 * stay in place.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => {
    const comment = toComment(row.comment);
    return {
      ...comment,
      body: comment.archivedAt === null ? comment.body : "",
      author: toUser(row.author),
    };
  });

  const childrenOf = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = childrenOf.get(comment.parentId) ?? [];
    bucket.push(comment);
    childrenOf.set(comment.parentId, bucket);
  }

  const descendantsOf = (rootId: string): CommentWithAuthor[] => {
    const result: CommentWithAuthor[] = [];
    const queue = [...(childrenOf.get(rootId) ?? [])];

    while (queue.length > 0) {
      const next = queue.shift();
      if (!next) continue;
      result.push(next);
      queue.push(...(childrenOf.get(next.id) ?? []));
    }

    return result.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  };

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: descendantsOf(comment.id),
    }));
}

