import { describe, expect, it, beforeAll, afterAll } from "vitest";
import { resolveMentions } from "@/lib/mentions";
import { makeMember, makeUser } from "./helpers/factories";
import type { UserId } from "@/types/common";

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Issue } from "@/types/issue";

describe("scratch: duplicate handle mentions all of them", () => {
  it("resolves a shared handle to every matching member", () => {
    const A = "u-a" as UserId;
    const B = "u-b" as UserId;
    const members = [
      makeMember({ userId: A, user: makeUser({ id: A, email: "john@acme.com" }) }),
      makeMember({ userId: B, user: makeUser({ id: B, email: "john@other.com" }) }),
    ];
    expect(resolveMentions("hey @john", members).sort()).toEqual([A, B].sort());
  });
});

describe("scratch: deep thread + deleted placeholder", () => {
  let cleanup: () => void;
  let tenant: Tenant;
  let issue: Issue;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    tenant = await createTenant("scratch-thread");
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Scratch" }),
      tenant.userIds.owner,
      number,
    );
  });

  afterAll(() => cleanup());

  it("flattens reply-of-reply under the top-level comment, oldest first", async () => {
    const top = await commentRepo.insertComment(
      { orgId: tenant.org.id, issueId: issue.id, body: "top", parentId: null, mentionedUserIds: [] },
      tenant.userIds.owner,
    );
    const reply1 = await commentRepo.insertComment(
      { orgId: tenant.org.id, issueId: issue.id, body: "reply1", parentId: top.id, mentionedUserIds: [] },
      tenant.userIds.member,
    );
    const reply2 = await commentRepo.insertComment(
      { orgId: tenant.org.id, issueId: issue.id, body: "reply-to-reply", parentId: reply1.id, mentionedUserIds: [] },
      tenant.userIds.admin,
    );

    const thread = await commentRepo.listThread(tenant.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);
    expect(node?.replies.map((r) => r.id)).toEqual([reply1.id, reply2.id]);
  });

  it("keeps a deleted comment as a placeholder so its replies stay anchored", async () => {
    const top = await commentRepo.insertComment(
      { orgId: tenant.org.id, issueId: issue.id, body: "top2", parentId: null, mentionedUserIds: [] },
      tenant.userIds.owner,
    );
    const reply = await commentRepo.insertComment(
      { orgId: tenant.org.id, issueId: issue.id, body: "reply-under-deleted", parentId: top.id, mentionedUserIds: [] },
      tenant.userIds.member,
    );
    await commentRepo.archiveComment(tenant.org.id, top.id);

    const thread = await commentRepo.listThread(tenant.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);
    expect(node).toBeDefined();
    expect(node?.comment.archivedAt).not.toBeNull();
    expect(node?.comment.body).toBe("");
    expect(node?.replies.map((r) => r.id)).toEqual([reply.id]);
  });
});

